var REV={};Object.keys(D).forEach(function(l){var m=D[l];Object.keys(m).forEach(function(k){REV[m[k]]=REV[m[k]]||k;REV[k]=k})});
var L='es';try{var q=new URLSearchParams(location.search).get('lang');if(q&&(q==='es'||D[q]))L=q;else{var st=localStorage.getItem('gms-lang');if(st&&(st==='es'||D[st]))L=st}}catch(e){}
var ORIG=new WeakMap(),ATTRS=['alt','aria-label','title','placeholder'];
function norm(v){return v.replace(/\s+/g,' ').trim()}
window.T=function(s){return L==='es'?s:((D[L]&&D[L][s])||s)};
